const state={screen:'select',mode:mobileViewport(window)?'p2p':'local',myHero:DEFAULT_PICKS[0],picks:[...DEFAULT_PICKS],picking:0,skillHero:DEFAULT_PICKS[0],skill:0,sound:true,room:null,assetsReady:false};const deviceService=new MatchAPI(),localRooms=new LocalRoomRegistry();let activeRecord=null;let engine=null,modal=null,canvas=null,ctx=null,remoteSnapshot=null,lastPhase='',lastLogFrame=0,toastTimer;const input=[{},{}],pendingInput=[{},{}],images=new Map();
// Keep devices and pointers independent; queue short presses until simulation consumes them.
const inputSources=[new Map(),new Map()],touchResetters=new Set(),padLatch=[{armed:true,up:false},{armed:true,up:false}];
function sourceInput(i,id,values,queue=true){values={...values};for(const key of ['heavy','dash','guard'])delete values[key];for(let slot=0;slot<4;slot++)if(playableHero(state.picks[i])?.abilities[slot]?.mvp.passive)delete values['s'+slot];const before=input[i];if(Object.values(values).some(Boolean))inputSources[i].set(id,values);else inputSources[i].delete(id);const next={};for(const v of inputSources[i].values())for(const [k,on]of Object.entries(v))if(on)next[k]=true;input[i]=Object.fromEntries(Object.keys({...before,...next}).map(k=>[k,!!next[k]]));if(queue)for(const [k,on]of Object.entries(next))if(on&&!before[k])pendingInput[i][k]=true;}
function sampledInput(i){return {...input[i],...pendingInput[i]};}let atlas=null;
try{state.sound=JSON.parse(localStorage.getItem('dota-duel-sound')||'true');const p=JSON.parse(localStorage.getItem('dota-duel-picks')||'null');state.picks=storedHeroPicks(p);}catch{}
