window.addEventListener('pointerdown',()=>{if(!music.unlocked||music.ctx?.state!=='running')music.unlock();officialMusic.unlock();});window.addEventListener('keydown',()=>{if(!music.unlocked||music.ctx?.state!=='running')music.unlock();officialMusic.unlock();});document.addEventListener('visibilitychange',()=>{music.lifecycle({hidden:document.hidden});officialMusic.lifecycle({hidden:document.hidden});});window.addEventListener('pagehide',()=>{music.lifecycle({pageAway:true});officialMusic.lifecycle({pageAway:true});});window.addEventListener('pageshow',()=>{music.lifecycle({pageAway:false});officialMusic.lifecycle({pageAway:false});});
