function requestOfficialPlay(){music.configure({musicEnabled:true});officialMusic.configure(true,music.settings.musicVolume);if(officialMusic.state==='error')officialMusic.retry();else if(!officialMusic.intent)officialMusic.play();}
function setOfficialVolume(value){music.configure({musicVolume:value});officialMusic.setVolume(music.settings.musicVolume);}
function audioDialog(){if(engine)engine.paused=true;if(state.room)sendRoom({type:'pause',value:true});release();closeOnly();const a=music.settings;overlay(`<div class="eyebrow">AUDIO</div><h2>音乐与音量</h2><p id="music-status" role="status"></p><div class="audio-grid"><label><input id="music-enabled" type="checkbox" ${a.musicEnabled?'checked':''}> 背景音乐</label><label>音乐音量 <input id="music-volume" aria-label="音乐音量" type="range" min="0" max="100" value="${Math.round(a.musicVolume*100)}"></label><label><input id="sfx-enabled" type="checkbox" ${a.sfxEnabled?'checked':''}> 游戏音效</label><label>音效音量 <input id="sfx-volume" aria-label="音效音量" type="range" min="0" max="100" value="${Math.round(a.sfxVolume*100)}"></label></div><div class="room-actions"><button id="music-play" class="button" ${OFFICIAL_ALBUM.src?'':'disabled'}>播放音乐</button><button id="music-stop" class="button">暂停音乐</button></div><p>${esc(OFFICIAL_ALBUM.title)} · ${esc(OFFICIAL_ALBUM.artist)}。菜单与对局连续播放同一首混音。</p><p>音乐开启后循环播放。切到后台会暂停，返回后可在这里继续。</p>`);refreshMusicStatus();$('#music-enabled').onchange=e=>{music.configure({musicEnabled:e.target.checked});officialMusic.configure(e.target.checked,music.settings.musicVolume);};$('#music-volume').oninput=e=>setOfficialVolume(+e.target.value/100);$('#sfx-enabled').onchange=e=>{state.sound=e.target.checked;music.configure({sfxEnabled:state.sound});};$('#sfx-volume').oninput=e=>music.configure({sfxVolume:+e.target.value/100});$('#music-play').onclick=()=>{requestOfficialPlay();$('#music-enabled').checked=true;};$('#music-stop').onclick=()=>officialMusic.stop();}


function beginRecord(opts){activeRecord=null;if(state.mode==='training')return;const observer=state.mode==='room'&&state.room?.role==='guest',transport=state.mode==='room'?'broadcastchannel':state.mode==='p2p'?'webrtc':'local';const record=new MatchRecord({mode:state.mode==='cpu'?'pve':'pvp',transport,heroes:state.picks,localId:opts.recordEpoch||null,observer,match:opts.match||null,service:observer?null:opts.service||deviceService,storage:localStorage,onchange:()=>{if(activeRecord===record)refreshRecordStatus();const r=state.room;if(r?.role==='host'&&r.transport!=='p2p'&&r.recordEpoch===record.localId)sendRoom({type:'recordStatus',record:record.view()});}});activeRecord=record;if(observer){record.status='awaiting_report';return;}if(state.mode==='cpu')record.beginPVE();else if(['local','room'].includes(state.mode))record.beginLocal();}
function finishRecord(reason='',game=engine?.snapshot?.()||remoteSnapshot){if(activeRecord&&game&&!activeRecord.payload)activeRecord.finish(game,reason);}
function refreshRecordStatus(){const r=activeRecord?.view(),out=$('#record-status');if(out&&r)out.textContent=recordStatusText(r.status)+(r.error?' · '+r.error:'');const summary=$('#record-summary');if(summary)summary.textContent=r?recordStatusText(r.status):'本地对局';const retry=app.querySelector('[data-action="retryRecord"]');if(retry){const canRetry=!!activeRecord&&!activeRecord.observer&&!!activeRecord.payload&&!!activeRecord.service&&['error','local'].includes(activeRecord.status);retry.hidden=!canRetry;retry.disabled=!canRetry;}}
function recordsDialog(){if(engine)engine.paused=true;release(true);closeOnly();let rows=[];try{rows=JSON.parse(localStorage.getItem('dota-duel-history')||'[]');}catch{}overlay(`<h2>对战记录</h2><p>对战与人机分开记录。此列表保留本浏览器最近200局；只有“战绩已保存”表示服务器已接收。中止或有争议的比赛不计胜负。</p><div class="record-list">${rows.length?rows.map(r=>`<article><strong>${r.mode==='pve'?'人机':'对战'} · ${esc(historicalHeroName(r,0))} vs ${esc(historicalHeroName(r,1))}</strong><p>${esc(r.result?.score?.join(' : ')||'—')} · ${Math.round((r.durationMs||0)/1000)}秒 · ${esc(recordStatusText(r.status))}</p><small>${esc(r.version)} · ${esc(new Date(r.startedAt).toLocaleString())}</small></article>`).join(''):'<p>尚无已结束的比赛。</p>'}</div>`);}
window.addEventListener('pagehide',()=>{finishRecord('left');const r=state.room;if(r?.reservation)localRooms.release(r.code,r.reservation.id,tabId).catch(()=>{});});
window.addEventListener('storage',e=>{if(e.key!=='dota-duel-history'||!activeRecord?.observer)return;try{const row=JSON.parse(e.newValue||'[]').find(v=>v.localId===activeRecord.localId);if(row)activeRecord.observeHost(row);}catch{}});

function p2pDialog(){if(location.protocol==='file:'){toast('P2P信令需要托管网址；离线文件可同屏对战');return;}closeOnly();overlay(`<div class="eyebrow">PEER TO PEER</div><h2>跨设备 P2P 对战</h2><p>两台设备打开同一网址，房主把六位数字口令告知对手。无需游戏账号；双方通过连接检查和战绩服务确认后开战。</p><div class="net-rule"><label>RTT 禁战方向<select id="net-direction" aria-label="RTT禁战方向"><option value="">请选择规则</option><option value="above">高于阈值禁止开战</option><option value="below">低于阈值禁止开战</option></select></label><label>阈值（毫秒）<input id="net-rtt" aria-label="RTT阈值毫秒" type="number" min="1" max="2000" placeholder="等待确认"></label></div><p>使用最近30次探测的P95 RTT；至少24次完成。双方还需满足抖动≤30ms、探测丢包≤5%，并各自点击准备。</p><button class="button primary" data-action="p2pCreate">创建 P2P 房间</button><hr><label>加入房间<input id="p2p-code" aria-label="六位数字对局口令" maxlength="6" inputmode="numeric" pattern="[0-9]{6}" placeholder="六位数字口令"></label><button class="button" data-action="p2pJoin">加入 P2P 房间</button><div class="notice">先尝试 WebRTC 直连，使用 Cloudflare STUN 查找公网地址。未配置 TURN；某些网络会连接失败，可重试或换网络。战斗数据不经过信令服务器。</div>`);}
function newP2P(role,policy){if(!isActiveHero(state.myHero))throw Error('英雄尚未开放');leaveRoom();state.room={transport:'p2p',role,player:role==='host'?0:1,code:'',connected:false,peer:'p2p-peer'};const hero=state.myHero;state.picks[role==='host'?0:1]=hero;const session=new PeerSession({role,hero,policy,available:!portraitViewport(window),onstate:x=>{if(p2pSession!==session)return;state.room.code=x.code;state.room.connected=x.connected&&!!x.version;state.room.peerPortrait=x.peerAvailable===false;if(state.room.peerPortrait&&state.screen==='battle'){release(true);if(engine)engine.paused=true;if(!modal)pausePeer();}if(isActiveHero(x.hero))state.picks[role==='host'?1:0]=x.hero;if(state.screen==='select')renderP2PLobby();},onmessage:m=>{if(!['input','snapshot','pause','rematch','p2pLobby'].includes(m.type))return;if(m.type==='input'){if(role!=='host'||!m.input||typeof m.input!=='object')return;const allowed=['left','right','up','jump','down','attack','s0','s1','s2','s3'];m.input=Object.fromEntries(allowed.filter(k=>m.input[k]===true).map(k=>[k,true]));}if(m.type==='snapshot'&&(role!=='guest'||!validRemoteSnapshot(m.snapshot)))return;handleRoomMessage(m);},onstart:({picks,match,service,pauseForOrientation})=>{start({mode:'p2p',p1:picks[0],p2:picks[1],match,service,pauseForOrientation});if(role==='guest')engine=null;},onfault:reason=>{finishRecord('disconnect');release();roomGuestInput={};roomGuestPending={};if(engine)engine.paused=true;if(state.room)state.room.connected=false;if(state.screen==='battle'){closeOnly();overlay(`<h2>连接已暂停</h2><p>${esc(reason)}</p><button class="button primary" data-action="p2pRetry">重新连接</button><button class="button" data-action="quit">返回选人</button>`);}else renderP2PLobby();}});p2pSession=session;renderP2PLobby();return session;}
const validatePeerSnapshot=createRemoteSnapshotValidator(runtimeHeroes,{roster:ACTIVE_ROSTER,heroRuleRegistry:releasedHeroRules});
function validRemoteSnapshot(g){return validatePeerSnapshot(g);}
function createP2P(){const policy={...DEFAULT_NET_POLICY,direction:$('#net-direction')?.value,rttMs:Number($('#net-rtt')?.value)};if(!validPolicy(policy))return toast('请先明确选择RTT方向及1–2000毫秒阈值');newP2P('host',policy).create();}
function joinP2P(){const code=$('#p2p-code')?.value.trim();if(!/^\d{6}$/.test(code||''))return toast('请输入六位数字口令');newP2P('guest',null).join(code);}
function renderP2PLobby(){if(!p2pSession||state.screen==='battle')return;const x=p2pSession.info();if(!$('#p2p-status')){closeOnly();overlay(`<div class="eyebrow">WEBRTC · ${x.role==='host'?'P1':'P2'}</div><h2>P2P 房间</h2><div class="room-code" id="p2p-room-code"></div><p id="p2p-status" role="status"></p><p id="p2p-rule"></p><pre id="p2p-quality" class="net-quality"></pre><p id="p2p-ready-state"></p><div class="room-actions"><button class="button" data-action="p2pReady">准备</button>${x.role==='host'?'<button class="button primary" data-action="p2pStart">双方开战</button>':''}<button class="button" data-action="p2pRetry">重新连接</button><button class="button" data-action="quit">离开房间</button></div><small>房间最多等待2分钟。断线后重新建房；不会恢复未完成的旧回合。探测丢包为DataChannel应用层超时比例。</small>`);}
 $('#p2p-room-code').textContent=x.code||'正在建立…';$('#p2p-status').textContent=x.error||x.gate.reason;$('#p2p-rule').textContent=validPolicy(x.policy)?`P95 RTT ${x.policy.direction==='above'?'>':'<'} ${x.policy.rttMs}ms 禁战 · 抖动≤30ms · 探测丢包≤5%`:'等待房主规则';const fmt=q=>q?`样本 ${q.samples}/24　RTT P95 ${q.p95?.toFixed(1)??'—'}ms　抖动 ${q.jitter?.toFixed(1)??'—'}ms　丢包 ${q.loss?.toFixed(1)??'—'}%`:'尚未收到';$('#p2p-quality').textContent='本端 '+fmt(x.quality)+'\n对端 '+fmt(x.peerQuality);$('#p2p-ready-state').textContent=`自己 ${x.ready?'已准备':'未准备'} · 对方 ${x.peerReady?'已准备':'未准备'}`;const ready=app.querySelector('[data-action="p2pReady"]');ready.disabled=!x.gate.ok;ready.textContent=x.ready?'取消准备':'准备';const begin=app.querySelector('[data-action="p2pStart"]');if(begin)begin.disabled=!x.gate.ok||!x.ready||!x.peerReady;}
function p2pLobby(){p2pSession?.returnToLobby();selection();renderP2PLobby();}
function p2pRematch(){if(activeRecord&&!['confirmed','aborted','disputed'].includes(activeRecord.status))return toast('等待战绩确认；保存失败时请先重试');sendRoom({type:'p2pLobby'});p2pLobby();}

window.DUEL={heroes:activeHeroes,catalog:heroCatalog,roster:ACTIVE_ROSTER,compatibility:GAME_COMPATIBILITY,DATA,state,get musicStatus(){return {...music.status(),...officialMusic.status(),sfx:music.status()};},get record(){return activeRecord?.view()||null;},get viewport(){return {portrait:portraitViewport(window),mobile:mobileViewport(window),safe:{...viewportSafe}};},get backend(){return {base:deviceService.base,registry:deviceService.registryStatus};},get network(){return p2pSession?.info();},start,selection,get engine(){return engine;},setInput:(i,v)=>{input[i]=v;engine?.setInput(i,v);},get snapshot(){return(engine||remoteSnapshot)?.snapshot?.()||remoteSnapshot;},get room(){return state.room;},createRoom,joinRoom,roomDialog,release,render:()=>engine&&draw(engine,performance.now())};
selection();

if(location.hostname==='127.0.0.1'&&location.port==='4174'){deviceService.loadRegistry().then(r=>toast(r.status==='verified'?'候选后端注册表已核对':'候选后端注册表不可用，新名单未获批准')).catch(e=>toast('候选后端：'+e.message));}
